// Copies the read-only exercise catalog out of the repo's data/exercises.json.
// The app never writes this file. Re-run after a catalog update; do not edit the output by hand.
import {readFileSync, writeFileSync} from 'node:fs';
import {dirname, join} from 'node:path';
import {fileURLToPath} from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const src = JSON.parse(readFileSync(join(root, 'data', 'exercises.json'), 'utf8'));
const rows = (src.exercises || []).map(e => ({
  id: String(e.id),
  name: String(e.name || e.id),
  type: String(e.type || ''),
  equipment: String(e.equipment || ''),
}));
if (!rows.length) throw new Error('exercises.json has no exercises');
const seen = new Set();
for (const r of rows) {
  if (!r.id || seen.has(r.id)) throw new Error('bad exercise id ' + r.id);
  seen.add(r.id);
}
const out = `/* Generated by scripts/sync-exercises.mjs from data/exercises.json. Do not edit. */\nexport type CatalogExercise = {id:string; name:string; type:string; equipment:string};\nexport const CATALOG: CatalogExercise[] = ${JSON.stringify(rows)};\n`;
writeFileSync(join(dirname(fileURLToPath(import.meta.url)), '..', 'src', 'data', 'exercises.slim.ts'), out);
console.log('catalog', rows.length);
